    std::vector<u32> queried_item_ids;
    std::vector<u32> played_sample_ids;
    std::vector<u32> played_sample_owners;
    std::vector<u32> events;
    i32 sample_return{0x5678};
    std::vector<u32> callback_modes;
    i32 callback_return{0x1234};
