        guardian.interaction_mode = 1U;
        guardian.first_dynamic_min_y = 230;
        guardian.first_dynamic_max_y = 250;
        guardian.second_dynamic_min_y = 0;
        guardian.second_dynamic_max_y = 0;
        snapshot = {.cursor_y = 240U, .cursor_x = 620U};
